<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {RouterLink} from 'vue-router'
import {ArrowLeft,Building2,Users,ShieldCheck,MenuSquare,KeyRound,Activity,History,Search,RefreshCw,Plus,X} from 'lucide-vue-next'
import AppMark from '../components/AppMark.vue'
import {authState,authCall,loadIdentity,routeResource} from '../services/auth'
import {administration,jsonValue,exportAdminPage,type AdminRow,type AdminCatalog} from '../services/administration'

type Section='tenants'|'users'|'roles'|'grants'|'menus'|'sessions'|'operations'|'history'
const user=computed(()=>authState.user),section=ref<Section>('tenants'),tenantId=ref(user.value?.tenantId??'')
const catalog=ref<AdminCatalog|null>(null),tenantOptions=ref<AdminRow[]>([]),roleOptions=ref<AdminRow[]>([])
const rows=ref<AdminRow[]>([]),keys=ref<AdminRow[]>([]),total=ref(0),page=ref(1),size=20,q=ref(''),status=ref(''),logAll=ref(true)
const loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),sessionUser=ref(user.value?.id??''),tenantSearch=ref('')
const effective=ref<AdminRow|null>(null),historyRow=ref<AdminRow|null>(null)
const sections=computed(()=>[
 {id:'tenants',label:'租户管理',icon:Building2,caption:'工作空间与生命周期'},
 {id:'users',label:'用户管理',icon:Users,caption:'账号与登录状态'},
 {id:'roles',label:'角色与权限',icon:ShieldCheck,caption:'功能读取与操作权限'},
 {id:'grants',label:'用户授权',icon:KeyRound,caption:'成员与有效权限'},
 ...(user.value?.platformAdmin?[{id:'menus',label:'菜单管理',icon:MenuSquare,caption:'主系统入口与排序'}]:[]),
 {id:'sessions',label:'会话与密钥',icon:KeyRound,caption:'访问凭据与撤销'},
 {id:'operations',label:'操作日志',icon:Activity,caption:'请求结果与追踪'},
 {id:'history',label:'授权与变更记录',icon:History,caption:'配置前后对照'},
])
const current=computed(()=>sections.value.find(s=>s.id===section.value))
const tenantName=computed(()=>tenantOptions.value.find(t=>t.id===tenantId.value)?.name??user.value?.tenants.find(t=>t.id===tenantId.value)?.name??'当前租户')
const canGrant=computed(()=>user.value?.platformAdmin||user.value?.role==='OWNER')
const logSection=computed(()=>['operations','history'].includes(section.value))
const columns=computed(()=>({tenants:['name','members','enabled','createdAt'],users:['username','id','displayName','email','verified','enabled','platformAdmin'],roles:['name','description','enabled','assignments'],grants:['username','email','role','customRoles'],menus:['label','path','parentId','permission','sortOrder','enabled'],sessions:['id','tenantId','createdAt','expiresAt'],operations:['createdAt','username','method','path','status','durationMs','traceId'],history:['createdAt','username','action','target','tenantId']}[section.value]))
const labels:Record<string,string>={name:'名称',members:'成员数',enabled:'状态',createdAt:'时间',username:'账号',displayName:'显示名称',email:'邮箱',verified:'登录资格',platformAdmin:'平台身份',description:'说明',assignments:'分配数',role:'固定角色',customRoles:'自定义角色',label:'菜单名称',path:'路径',parentId:'上级',permission:'访问权限',sortOrder:'顺序',id:'记录编号',tenantId:'所属租户',expiresAt:'有效期至',method:'方法',status:'状态码',durationMs:'耗时 / ms',traceId:'追踪编号',action:'操作',target:'对象'}
const roleLabels:Record<string,string>={OWNER:'所有者',ADMIN:'管理员',MEMBER:'成员',VIEWER:'只读成员'}
const actionLabels:Record<string,string>={ROLE_ASSIGN:'角色授权',ROLE_CREATE:'创建角色',ROLE_UPDATE:'更新角色',ROLE_DELETE:'删除角色',MENU_CREATE:'创建菜单',MENU_UPDATE:'更新菜单',MENU_DELETE:'删除菜单',PLATFORM_GRANT:'平台管理员授权',TENANT_UPDATE:'更新租户',TENANT_CREATE_ADMIN:'创建租户',ACCOUNT_PROVISION:'创建账号',ACCOUNT_UPDATE:'更新账号',ADMIN_RESET_INITIAL:'重置初始密码',LOGIN:'登录',LOGIN_FAILED:'登录失败',LOGOUT:'退出登录',PASSWORD_CHANGE:'修改密码',ADMIN_SESSION_REVOKE:'撤销会话',ADMIN_KEY_REVOKE:'撤销密钥',MEMBER_ROLE:'成员角色变更',MEMBER_REMOVE:'移除成员'}
const time=(value:unknown)=>value?new Date(String(value)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'
function display(row:AdminRow,key:string){const value=row[key];if(key==='createdAt'||key==='expiresAt')return time(value);if(key==='enabled')return value?'启用':'停用';if(key==='platformAdmin')return value?'平台管理员':'普通账号';if(key==='verified')return value?row.email?'可登录':'管理员创建':'待邮箱验证';if(key==='role')return roleLabels[value]??value;if(key==='action')return actionLabels[value]??value;if(key==='customRoles')return (jsonValue<string[]>(value)??[]).map(id=>roleOptions.value.find(r=>r.id===id)?.name??id).join('、')||'继承固定角色';if(key==='parentId')return rows.value.find(r=>r.id===value)?.label??(value?'上级菜单':'根目录');if(value==null||value==='')return '—';return String(value)}

let alive=true,version=0
async function loadTenants(){const result=await administration.get<{items:AdminRow[]}>('/tenants',{q:tenantSearch.value,size:100});if(alive){tenantOptions.value=result.items;if(!tenantOptions.value.some(t=>t.id===tenantId.value)){const known=user.value?.tenants.find(t=>t.id===tenantId.value);if(known)tenantOptions.value.unshift(known)}}}
async function load(){
  const ticket=++version,tab=section.value,scope=tenantId.value;loading.value=true;error.value='';rows.value=[];keys.value=[];effective.value=null;historyRow.value=null
  try{
    const roles=tab==='roles'||tab==='grants'?await administration.get<AdminRow[]>('/roles',{tenantId:scope}):null
    let result:AdminRow[]|{items:AdminRow[];total:number}
    const params={tenantId:scope,page:page.value,size,q:q.value}
    if(tab==='roles')result=roles!
    else if(tab==='grants')result=await administration.get<AdminRow[]>('/members',{tenantId:scope})
    else if(tab==='menus')result=await administration.get<AdminRow[]>('/menus')
    else if(tab==='sessions'){
      const resultPair=await Promise.all([administration.get<AdminRow[]>('/sessions',{tenantId:scope,userId:sessionUser.value}),administration.get<AdminRow[]>('/keys',{tenantId:scope})]);result=resultPair[0];if(alive&&ticket===version)keys.value=resultPair[1]
    }else result=await administration.get<{items:AdminRow[];total:number}>('/'+tab,{...params,...(logSection.value&&user.value?.platformAdmin&&logAll.value?{tenantId:undefined}:{}),...(tab==='operations'&&status.value?{status:status.value}:{})})
    if(!alive||ticket!==version)return
    if(roles)roleOptions.value=roles
    if(Array.isArray(result)){const filtered=q.value.trim()?result.filter(r=>JSON.stringify(r).toLowerCase().includes(q.value.trim().toLowerCase())):result;total.value=filtered.length;rows.value=filtered.slice((page.value-1)*size,page.value*size)}else {rows.value=result.items;total.value=result.total}
  }catch(e){if(alive&&ticket===version)error.value=e instanceof Error?e.message:'读取后台数据失败。'}finally{if(alive&&ticket===version)loading.value=false}
}
watch([section,tenantId],()=>{page.value=1;q.value='';status.value='';message.value='';closeEditor();void load()})
async function search(){page.value=1;await load()}
async function changePage(delta:number){page.value+=delta;await load()}
async function refresh(){await load();if(section.value==='tenants')await loadTenants()}

type Editor={kind:'tenant'|'user'|'role'|'grant'|'menu'|'confirm';title:string;form:AdminRow;detail?:string;action?:()=>Promise<unknown>}
const editor=ref<Editor|null>(null),dialog=ref<HTMLElement|null>(null)
let previousFocus:HTMLElement|null=null
async function openEditor(value:Editor){error.value='';previousFocus=document.activeElement as HTMLElement;editor.value=value;await nextTick();dialog.value?.querySelector<HTMLElement>('input,select,button')?.focus()}
function closeEditor(){if(busy.value)return;editor.value=null;previousFocus?.focus()}
function trap(event:KeyboardEvent){if(event.key==='Escape'){closeEditor();return}if(event.key!=='Tab')return;const elements=[...(dialog.value?.querySelectorAll<HTMLElement>('input:not(:disabled),select:not(:disabled),textarea:not(:disabled),button:not(:disabled),a[href]')??[])];if(!elements.length)return;const first=elements[0]!,last=elements.at(-1)!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
function edit(row?:AdminRow){
 if(section.value==='tenants')void openEditor({kind:'tenant',title:row?'编辑租户':'新建租户',form:{id:row?.id,name:row?.name??'',enabled:row?.enabled??true,ownerId:user.value?.id}})
 if(section.value==='users')void openEditor({kind:'user',title:row?'编辑用户':'创建用户',form:{id:row?.id,username:row?.username??'',displayName:row?.displayName??'',email:'',enabled:row?.enabled??true}})
 if(section.value==='roles')void openEditor({kind:'role',title:row?'编辑角色与权限':'创建自定义角色',form:{id:row?.id,name:row?.name??'',description:row?.description??'',permissions:jsonValue(row?.permissions??[])??[],enabled:row?.enabled??true,version:row?.version??0}})
 if(section.value==='grants')void openEditor({kind:'grant',title:row?'调整用户授权':'添加并授权成员',form:{userId:row?.id??null,identifier:row?.username??'',role:row?.role??'MEMBER',customRoles:jsonValue(row?.customRoles??[])??[]}})
 if(section.value==='menus')void openEditor({kind:'menu',title:row?'编辑菜单':'新建菜单 / 分组',form:{id:row?.id,parentId:row?.parentId??'',label:row?.label??'',path:row?.path??'',sortOrder:row?.sortOrder??0,enabled:row?.enabled??true,version:row?.version??0}})
}
function confirm(title:string,detail:string,action:()=>Promise<unknown>){void openEditor({kind:'confirm',title,detail,action,form:{}})}
async function save(){
  if(busy.value||!editor.value)return;busy.value=true;error.value=''
  const value=editor.value,form={...value.form},scope=tenantId.value
  try{
    if(value.kind==='confirm')await value.action?.()
    if(value.kind==='tenant')await administration.post('/tenants'+(form.id?'/'+form.id:''),form.id?{name:form.name,enabled:form.enabled}:{name:form.name,ownerId:form.ownerId})
    if(value.kind==='user')await administration.post('/users'+(form.id?'/'+form.id:''),form.id?{displayName:form.displayName,enabled:form.enabled}:{username:form.username,displayName:form.displayName,email:form.email},scope)
    if(value.kind==='role')await administration.post('/roles'+(form.id?'/'+form.id:''),{name:form.name,description:form.description,permissions:form.permissions,enabled:form.enabled,version:form.version},scope)
    if(value.kind==='grant')await administration.post('/grants',{userId:form.userId,identifier:form.identifier,role:form.role,customRoles:form.customRoles},scope)
    if(value.kind==='menu'){const resource=routeResource(form.path);await administration.post('/menus'+(form.id?'/'+form.id:''),{parentId:form.parentId||null,label:form.label,path:form.path||null,permission:form.path?resource+'.read':'',sortOrder:form.sortOrder,enabled:form.enabled,version:form.version})}
    editor.value=null;message.value='操作已完成，变更已记录。';await refresh()
  }catch(e){error.value=e instanceof Error?e.message:'保存失败，未关闭当前表单。'}finally{busy.value=false;if(!editor.value)previousFocus?.focus()}
}
async function inspect(row:AdminRow){historyRow.value=null;effective.value=null;try{effective.value=await administration.get('/effective',{userId:row.id,tenantId:tenantId.value})}catch(e){error.value=e instanceof Error?e.message:'读取有效权限失败。'}}
function showSessions(row:AdminRow){sessionUser.value=row.id;section.value='sessions'}
function deleteItem(row:AdminRow){const type=section.value==='roles'?'roles':'menus';confirm('确认删除'+(type==='roles'?'角色':'菜单'),`将删除「${row.name??row.label}」。已有分配的角色和存在子项的菜单无法删除。`,()=>administration.post(`/${type}/${row.id}/delete`,{},type==='roles'?tenantId.value:undefined))}
function reset(row:AdminRow){confirm('重置初始密码',`将 ${row.username} 的密码重置为 ${row.username}123456，并撤销全部会话和接口密钥；下次登录必须修改。`,()=>authCall(`/admin/users/${row.id}/reset-initial`,{}))}
function platform(row:AdminRow){confirm(row.platformAdmin?'撤销平台管理员':'授予平台管理员',`「${row.username}」的平台身份将改变。这项权限可以管理所有租户和账号，当前会话和密钥将被撤销。`,()=>administration.post(`/users/${row.id}/platform`,{enabled:!row.platformAdmin}))}
onMounted(async()=>{try{catalog.value=await administration.get<AdminCatalog>('/catalog');await loadTenants();await load()}catch(e){error.value=e instanceof Error?e.message:'后台初始化失败。'}})
onUnmounted(()=>{alive=false;++version})
</script>

<template>
 <div class="admin-shell">
  <aside class="admin-sidebar"><div class="admin-brand"><AppMark/><div><strong>AI-QUANT</strong><span>ADMINISTRATION</span></div></div><p class="nav-caption">管理控制台</p><nav aria-label="后台导航"><button v-for="item in sections" :key="item.id" :class="{active:section===item.id}" :aria-current="section===item.id?'page':undefined" :disabled="busy" @click="section=item.id as Section"><component :is="item.icon" :size="18"/><span>{{item.label}}<small>{{item.caption}}</small></span></button></nav><div class="sidebar-foot"><span>{{user?.platformAdmin?'平台管理范围':'当前租户管理范围'}}</span><p>{{user?.username}}</p><RouterLink to="/overview"><ArrowLeft :size="15"/> 返回主系统</RouterLink></div></aside>
  <main class="admin-main"><header class="admin-header"><div><p class="kicker">ACCESS / ORGANIZATION / AUDIT</p><h1>{{current?.label}}</h1><p>{{current?.caption}} · {{user?.platformAdmin?'平台管理员':'租户'+(roleLabels[user?.role??'']??'管理员')}}</p></div><RouterLink class="return" to="/overview"><ArrowLeft :size="16"/>返回主系统</RouterLink></header>
   <section class="scope-panel" aria-label="管理范围"><div><small>MANAGEMENT SCOPE</small><strong>{{tenantName}}</strong><span>{{tenantId}}</span></div><label>选择租户<select v-model="tenantId" :disabled="busy||!user?.platformAdmin" aria-label="后台管理租户"><option v-for="tenant in tenantOptions" :key="tenant.id" :value="tenant.id">{{tenant.name}}{{tenant.enabled===false?' · 已停用':''}}</option></select></label><form v-if="user?.platformAdmin" class="tenant-search" @submit.prevent="loadTenants"><label>查找租户<input v-model="tenantSearch" placeholder="输入名称" aria-label="查找租户"/></label><button :disabled="busy">查找</button></form></section>
   <p v-if="message" class="success" role="status">{{message}}</p><p v-if="error&&!editor" class="notice" role="alert">{{error}} <button @click="refresh">重试</button></p>
   <section class="admin-board"><header class="board-heading"><div><h2>{{current?.label}}</h2><p v-if="section==='roles'">固定所有者／管理员保留管理权限。成员分配自定义角色后，业务权限由自定义角色集合决定；未分配时继承固定角色。</p><p v-else-if="section==='menus'">配置主系统菜单的名称、层级、顺序与可见性。隐藏菜单不会替代 API 授权。</p><p v-else-if="section==='grants'">按租户授权；角色和账号状态在每次业务请求中重新校验。只读角色始终不能获得写权限。</p><p v-else-if="section==='operations'">记录账号操作、后台查询和业务写请求的状态、耗时及追踪号，不保存请求正文、密码和令牌。</p><p v-else-if="section==='history'">查看角色、成员、租户、菜单及账号变更；新后台变更支持前后对照。</p><p v-else-if="section==='users'">管理平台账号与登录状态。没有绑定邮箱的管理员创建账号，仍需首次改密。</p><p v-else-if="section==='sessions'">撤销立即阻止后续访问；已发起的业务请求仍按请求开始时的授权执行。</p><p v-else>管理租户生命周期；停用时撤销该租户的会话与接口密钥，保留业务记录。</p></div><button class="refresh" :disabled="loading||busy" @click="refresh"><RefreshCw :size="15"/>刷新</button></header>
    <form class="toolbar" @submit.prevent="search"><label class="search"><Search :size="15"/><input v-model="q" placeholder="搜索当前模块" aria-label="后台搜索"/></label><select v-if="section==='operations'" v-model="status" aria-label="操作状态"><option value="">全部状态码</option><option>200</option><option>400</option><option>401</option><option>403</option><option>409</option><option>500</option><option>503</option></select><label v-if="logSection&&user?.platformAdmin" class="inline"><input type="checkbox" v-model="logAll"/>所有租户记录</label><label v-if="section==='sessions'">查询用户 ID<input v-model="sessionUser" aria-label="查询会话用户 ID" required/></label><button :disabled="busy||loading">查询</button><button v-if="['tenants','users','menus'].includes(section)&&user?.platformAdmin||section==='roles'||section==='grants'&&canGrant" class="primary" type="button" :disabled="busy" @click="edit()"><Plus :size="15"/>{{section==='grants'?'添加授权':'新增'}}</button><button v-if="logSection" type="button" :disabled="!rows.length||loading" @click="exportAdminPage(rows,`aiquant-${section}-page-${page}`)">导出当前页 CSV</button></form>
    <p v-if="loading" class="empty" role="status">正在读取管理记录…</p>
    <div v-else class="admin-table-wrap"><table><thead><tr><th v-for="key in columns" :key="key">{{labels[key]}}</th><th v-if="!['operations'].includes(section)">操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td v-for="key in columns" :key="key" :class="{mono:['id','tenantId','path','traceId','permission','durationMs'].includes(key),failed:key==='status'&&row.status>=400}">{{display(row,key)}}</td><td v-if="section!=='operations'" class="row-actions"><template v-if="section==='tenants'&&user?.platformAdmin"><button @click="edit(row)" :disabled="busy">编辑</button></template><template v-if="section==='users'"><button v-if="user?.platformAdmin" @click="edit(row)">编辑</button><button v-if="user?.platformAdmin" @click="reset(row)">重置密码</button><button v-if="user?.platformAdmin&&row.id!==user.id" @click="platform(row)">{{row.platformAdmin?'撤销平台身份':'平台授权'}}</button><button @click="showSessions(row)">会话</button></template><template v-if="section==='roles'"><button @click="edit(row)">编辑权限</button><button @click="deleteItem(row)">删除</button></template><template v-if="section==='grants'"><button @click="inspect(row)">有效权限</button><button v-if="canGrant" @click="edit(row)">调整授权</button><button @click="confirm('移除租户成员',`将移除 ${row.username} 的租户成员身份并撤销相关访问。`,()=>administration.post(`/members/${row.id}/remove`,{},tenantId))">移除</button></template><template v-if="section==='menus'"><button @click="edit(row)">编辑</button><button @click="deleteItem(row)">删除</button></template><button v-if="section==='sessions'" @click="confirm('撤销会话','该登录会话将立即失效；如果撤销自己的会话，将需要重新登录。',()=>administration.post(`/sessions/${row.id}/revoke`,{},tenantId))">撤销</button><button v-if="section==='history'" @click="historyRow=row;effective=null">变更详情</button></td></tr><tr v-if="!rows.length"><td :colspan="columns.length+1" class="empty">暂无符合条件的记录。</td></tr></tbody></table></div>
    <footer class="pagination"><span>共 {{total}} 条 · 第 {{page}} / {{Math.max(1,Math.ceil(total/size))}} 页</span><button :disabled="page<=1||loading||busy" @click="changePage(-1)">上一页</button><button :disabled="page*size>=total||loading||busy" @click="changePage(1)">下一页</button></footer>
   </section>
   <section v-if="effective" class="detail-panel"><header><h2>用户有效权限</h2><button @click="effective=null">收起</button></header><p>{{roleLabels[effective.role]}} {{effective.platformAdmin?'· 平台管理员':''}}</p><div class="permission-tags"><span v-for="code in effective.permissions" :key="code">{{code}}</span></div><p>所有者、租户管理员和平台管理员保留其固定管理权限；自定义业务角色不授予平台管理身份。</p></section>
   <section v-if="historyRow" class="detail-panel"><header><h2>{{actionLabels[historyRow.action]??historyRow.action}}</h2><button @click="historyRow=null">收起</button></header><p>{{time(historyRow.createdAt)}} · {{historyRow.username??'系统 / 未登录'}} · {{historyRow.target}}</p><div class="diff"><article><h3>变更前</h3><pre>{{JSON.stringify(jsonValue(historyRow.beforeState),null,2)??'未记录 / 不适用'}}</pre></article><article><h3>变更后</h3><pre>{{JSON.stringify(jsonValue(historyRow.afterState),null,2)??'未记录 / 不适用'}}</pre></article></div></section>
   <section v-if="section==='sessions'" class="admin-board"><header class="board-heading"><div><h2>当前租户接口密钥</h2><p>仅展示管理元数据，密钥原文不会再次显示。</p></div></header><div class="admin-table-wrap"><table><thead><tr><th>名称</th><th>用户</th><th>权限</th><th>有效期</th><th>操作</th></tr></thead><tbody><tr v-for="key in keys" :key="key.id"><td>{{key.name}}</td><td>{{key.username}}</td><td>{{key.scope}}</td><td>{{time(key.expiresAt)}}</td><td><button @click="confirm('撤销接口密钥',`「${key.name}」将无法继续访问业务 API。`,()=>administration.post(`/keys/${key.id}/revoke`,{},tenantId))">撤销</button></td></tr><tr v-if="!keys.length"><td colspan="5" class="empty">当前租户没有接口密钥。</td></tr></tbody></table></div></section>
  </main>
  <div v-if="editor" class="modal-overlay" @keydown="trap" @click.self="closeEditor"><section ref="dialog" class="editor" role="dialog" aria-modal="true" aria-labelledby="editor-title"><header><h2 id="editor-title">{{editor.title}}</h2><button aria-label="关闭编辑" :disabled="busy" @click="closeEditor"><X :size="19"/></button></header><p v-if="error" class="notice" role="alert">{{error}}</p><form @submit.prevent="save"><fieldset :disabled="busy">
   <template v-if="editor.kind==='tenant'"><label>租户名称<input v-model="editor.form.name" required maxlength="80" aria-label="租户名称"/></label><label v-if="!editor.form.id">所有者用户 ID<input v-model="editor.form.ownerId" required aria-label="租户所有者 ID"/></label><label v-else class="inline"><input type="checkbox" v-model="editor.form.enabled"/>启用租户</label><p>默认租户不能停用；停用其他租户会撤销其登录会话和接口密钥。</p></template>
   <template v-if="editor.kind==='user'"><label v-if="!editor.form.id">账号<input v-model="editor.form.username" required pattern="[a-z][a-z0-9_]{2,31}" maxlength="32" aria-label="后台创建账号"/></label><label>显示名称<input v-model="editor.form.displayName" maxlength="80" aria-label="用户显示名称"/></label><label v-if="!editor.form.id">邮箱（可选）<input v-model="editor.form.email" type="email" maxlength="254" aria-label="后台创建邮箱"/></label><label v-else class="inline"><input type="checkbox" v-model="editor.form.enabled"/>启用账号</label><p v-if="!editor.form.id">初始密码为「账号 + 123456」。填写邮箱时需要真实 SMTP 验证；未填写时按管理员创建账号处理，之后由用户绑定验证邮箱。</p></template>
   <template v-if="editor.kind==='role'"><label>角色名称<input v-model="editor.form.name" required maxlength="80" aria-label="角色名称"/></label><label>角色说明<textarea v-model="editor.form.description" maxlength="400" rows="2"/></label><label class="inline"><input type="checkbox" v-model="editor.form.enabled"/>启用角色</label><div class="permission-matrix"><div class="matrix-head"><b>业务模块</b><b>读取</b><b>操作</b></div><div v-for="permission in catalog?.permissions??[]" :key="permission.module"><span>{{permission.label}}</span><input type="checkbox" :value="permission.read" v-model="editor.form.permissions" :aria-label="`${permission.label}读取权限`"/><input type="checkbox" :value="permission.write" v-model="editor.form.permissions" :aria-label="`${permission.label}操作权限`"/></div></div><p>只有操作权限而没有读取权限时，页面入口仍不可见。停用已分配角色会收回其权限，不恢复为默认成员权限。</p></template>
   <template v-if="editor.kind==='grant'"><label>账号或邮箱<input v-model="editor.form.identifier" :disabled="Boolean(editor.form.userId)" required aria-label="授权账号或邮箱"/></label><label>固定角色<select v-model="editor.form.role" aria-label="授权固定角色"><option v-for="(label,key) in roleLabels" :key="key" :value="key">{{label}}</option></select></label><p>自定义角色不改变所有者／管理员的管理权；只读成员不会因为自定义角色而获得写权限。</p><div class="role-choices"><label v-for="role in roleOptions" :key="role.id" class="inline"><input type="checkbox" :value="role.id" v-model="editor.form.customRoles"/>{{role.name}} {{role.enabled?'':'· 已停用'}}</label><p v-if="!roleOptions.length">还没有自定义角色，可先在“角色与权限”中创建。</p></div><p>不选择自定义角色时继承固定角色；选择后按这些角色的权限集合授权。</p></template>
   <template v-if="editor.kind==='menu'"><label>菜单名称<input v-model="editor.form.label" required maxlength="80" aria-label="菜单名称"/></label><label>上级菜单<select v-model="editor.form.parentId" aria-label="上级菜单"><option value="">根目录</option><option v-for="menu in rows.filter(r=>r.id!==editor?.form.id)" :key="menu.id" :value="menu.id">{{menu.label}}</option></select></label><label>系统路由<select v-model="editor.form.path" aria-label="菜单路由"><option value="">分组（无跳转）</option><option v-for="path in catalog?.routes??[]" :key="path">{{path}}</option></select></label><label>排序<input v-model.number="editor.form.sortOrder" type="number" min="-10000" max="10000" required/></label><label class="inline"><input type="checkbox" v-model="editor.form.enabled"/>显示菜单</label><p>只允许已存在的系统页面，菜单不能注入脚本或外部地址。页面的 API 权限由角色单独控制。</p></template>
   <p v-if="editor.kind==='confirm'" class="confirm-detail">{{editor.detail}}</p>
  </fieldset><footer><button type="button" :disabled="busy" @click="closeEditor">取消</button><button class="primary" :disabled="busy">{{busy?'正在保存…':editor.kind==='confirm'?'确认操作':'保存'}}</button></footer></form></section></div>
 </div>
</template>

